# Let's examine character-by-character changes
inputs = ['fkc', 'ive', 'wgk', 'ewjgw', 'cua']
outputs = ['fgzwkww', 'ive', 'wggz', 'ewfvgw', 'wkwwuh']

print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\n'{inp}' -> '{out}':")
    print(f"Length: {len(inp)} -> {len(out)}")

    # Show character by character differences
    min_len = min(len(inp), len(out))
    for j in range(min_len):
        if inp[j] != out[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")

    if len(inp) != len(out):
        if len(inp) < len(out):
            print(f"  Extra chars in output: '{out[len(inp):]}'")
        else:
            print(f"  Extra chars in input: '{inp[len(out):]}'")

